{
   plan: {
      name: string;
      price?: number;

      orgdataSizeLimit: number;               // MB
      monthlyShareLimit: number;
      monthlyDownloadLimit: number;
   };
   metrics: {
     orgdataUsedSize: number;                // MB
     monthlySharedCount: number;
     monthlyDownloadCount: number;
   };
}

https://vks.vatech.com/pages/viewpage.action?pageId=211014626 #0211 회의록에 따라, 타입 정의 없이 object를 body로 제공하는 방식으로 변경합니다. 
{ }

{
  view: {
    ioSensorRatioSetting: string;
    ioCameraRatioSetting: string;
    captureImageRatioSetting: string;
  };
  ctView: {
    ct3DViewSetting: {
      defaultZoomRate: number;
    };
    vrColoringAdjustSetting: {
      opacity: number;
      brightness: number;
      contrast: number;
    };
    mprViewSetting: {
      defaultThickness: number;
      defaultInterval: string;
      defaultZoom: number;
    };
  };
  tools: {
    useToolGuide: boolean;
    grid: {
      spacing: number;
      color: {
        name: string;
        opacity: number;
      };
      width: number;
    };
  };
  measurement: {
    visibleUnit: boolean;
    angleColor: string;
    lengthColor: string;
    fontSize: number;
    lineThickness: number;
    decimalPlaces: number;
  };
  annotation: {
    freeDraw: {
      thickness: number;
      color: string;
    };
    pointer: {
      thickness: number;
      color: string;
    };
  };
};

